import{_ as s,a0 as p,w as a,s as r,ao as i,I as l,x as u,a1 as o,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"Ubuntu 15.04 終於可以讓你將菜單設置為 ‘始終可見’ | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 15.04 終於可以讓你將菜單設置為 ‘始終可見’ | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 15.04 終於可以讓你將菜單設置為 ‘始終可見’ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 15.04 終於可以讓你將菜單設置為 ‘始終可見’ | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20150119 Ubuntu 15.04 Finally Lets You Set Menus ToAlways Show","title":"Ubuntu 15.04 終於可以讓你將菜單設置為 ‘始終可見’","tag":"201503","desc":""},"relativePath":"201503/20150119 Ubuntu 15.04 Finally Lets You Set Menus ToAlways Show.md","filePath":"[post].md"}'),d={name:"201503/20150119 Ubuntu 15.04 Finally Lets You Set Menus ToAlways Show.md"};function b(m,t,w,f,T,g){const n=p("Link");return a(),r("div",null,[t[18]||(t[18]=i('<h1 id="ubuntu-15-04-終於可以讓你將菜單設置為-始終可見" tabindex="-1">Ubuntu 15.04 終於可以讓你將菜單設置為 ‘始終可見’ <a class="header-anchor" href="#ubuntu-15-04-終於可以讓你將菜單設置為-始終可見" aria-label="Permalink to “Ubuntu 15.04 終於可以讓你將菜單設置為 ‘始終可見’”">​</a></h1><p><strong>如果你不喜歡 Unity 的全局菜單在你的鼠標離開後就淡出你的視野，在 Ubuntu 15.04 稍微做點工作就可以留住菜單。</strong></p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/02/locally-integrated-menus-in-ubuntu.png" alt=""></p><p>最新的Ubuntu 15.04的Unity界面通過在“提議（Proposed）”通道提供了一個選項，<strong>使應用程序菜單在Ubuntu中始終可見</strong>。</p><p>這是個不會淡出，也不會過段時間就消失的菜單。</p><p>最大的缺點是它目前只能通過<code>dconf</code>來控制，而不是常規的面向用户的選項設置。</p><p>我希望（如果預計沒有的話）在之後的開發中，能有一個設置這個特性的選項被加入到Ubuntu的【系統設置】&gt;【外觀】部分。</p><p>現在，如果你使用的是 Ubuntu 15.04，並啓用了“提議（Proposed）”的更新通道後，你可以在dconf 的com&gt;canonical&gt;Unity&gt;‘always show menus’ 中找到這個開關。</p><h3 id="遲到總比沒有要好" tabindex="-1">遲到總比沒有要好? <a class="header-anchor" href="#遲到總比沒有要好" aria-label="Permalink to “遲到總比沒有要好?”">​</a></h3><p>開發者們計劃在Ubuntu 14.04 LTS的下一個SRU中反向移植這個選項（假設在測試階段沒有任何意外發生）。</p><p>本地集成菜單（LIM）在Ubuntu 14.04 LTS 中的首次亮相就贏得了讚譽，其被廣泛認為在那些喜歡隱藏方式的與那些不喜歡必須使用鼠標和觸摸板的人之間的最佳的折衷方案。</p><p>雖然在Unity方面本地集成菜單減少了不少批評，不過默認的“淡入/淡出”行為總是還讓人不爽。</p>',12)),l("p",null,[t[2]||(t[2]=u("在Ubuntu 過去的幾個版本中已經能夠看到他們在積極解決早期的用户體驗中的幾個痛點。經過了幾年，在TODO列表中",-1)),o(n,{href:"http://www.omgubuntu.co.uk/2014/02/locally-integrated-menus-ubuntu-14-04"},{default:e(()=>[...t[0]||(t[0]=[u("我們去年終於看到了本地集成菜單",-1)])]),_:1}),t[3]||(t[3]=u("，以及通過",-1)),o(n,{href:"http://www.omgubuntu.co.uk/2014/03/minimize-click-launcher-option-ubuntu-14-04"},{default:e(()=>[...t[1]||(t[1]=[u("點擊應用圖標來實現Unity 啓動器中應用的最小化及恢復的選項",-1)])]),_:1}),t[4]||(t[4]=u("。",-1))]),t[19]||(t[19]=l("p",null,"一年以來我們終於看到了一個使應用程序菜單始終顯示的選項，無論我們的鼠標在哪裏。遲來總比沒有好，對不對？",-1)),t[20]||(t[20]=l("hr",null,null,-1)),l("p",null,[t[6]||(t[6]=u("via: ",-1)),o(n,{href:"http://www.omgubuntu.co.uk/2015/01/ubuntu-15-04-always-show-menu-bar-option"},{default:e(()=>[...t[5]||(t[5]=[u("http://www.omgubuntu.co.uk/2015/01/ubuntu-15-04-always-show-menu-bar-option",-1)])]),_:1})]),l("p",null,[t[10]||(t[10]=u("作者：",-1)),o(n,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:e(()=>[...t[7]||(t[7]=[u("Joey-Elijah Sneddon",-1)])]),_:1}),t[11]||(t[11]=u(" 譯者：",-1)),o(n,{href:"https://github.com/JeffDing"},{default:e(()=>[...t[8]||(t[8]=[u("JeffDing",-1)])]),_:1}),t[12]||(t[12]=u(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:e(()=>[...t[9]||(t[9]=[u("wxy",-1)])]),_:1})]),l("p",null,[t[15]||(t[15]=u("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[13]||(t[13]=[u("LCTT",-1)])]),_:1}),t[16]||(t[16]=u(" 原創翻譯，",-1)),o(n,{href:"http://linux.cn/"},{default:e(()=>[...t[14]||(t[14]=[u("Linux中國",-1)])]),_:1}),t[17]||(t[17]=u(" 榮譽推出",-1))])])}const S=s(d,[["render",b]]);export{L as __pageData,S as default};
